css:
.d-nested-dialog-focus-return{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-nested-dialog-focus-return *,.d-nested-dialog-focus-return *::before,.d-nested-dialog-focus-return *::after{box-sizing:border-box}
.d-nested-dialog-focus-return [hidden]{display:none!important}
.d-nested-dialog-focus-return .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-nested-dialog-focus-return .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-nested-dialog-focus-return label{display:block;margin:8px 0}
.d-nested-dialog-focus-return input,.d-nested-dialog-focus-return select,.d-nested-dialog-focus-return textarea,.d-nested-dialog-focus-return button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-nested-dialog-focus-return input:not([type=checkbox]):not([type=radio]),.d-nested-dialog-focus-return select,.d-nested-dialog-focus-return textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-nested-dialog-focus-return button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-nested-dialog-focus-return button:disabled{opacity:.5;cursor:default}
.d-nested-dialog-focus-return :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-nested-dialog-focus-return [aria-invalid=true]{border-color:var(--warn)!important}
.d-nested-dialog-focus-return .d-scroll{max-width:100%;overflow:auto}
.d-nested-dialog-focus-return table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-nested-dialog-focus-return th,.d-nested-dialog-focus-return td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-nested-dialog-focus-return caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-nested-dialog-focus-return progress{width:100%;accent-color:var(--ink)}
.d-nested-dialog-focus-return pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-nested-dialog-focus-return h3,.d-nested-dialog-focus-return p{margin:8px 0}
.d-nested-dialog-focus-return [aria-pressed=true],.d-nested-dialog-focus-return [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-nested-dialog-focus-return .d-grow{flex:1;min-width:100px}
.d-nested-dialog-focus-return summary{cursor:pointer;padding:6px 0}
.d-nested-dialog-focus-return ul,.d-nested-dialog-focus-return ol{padding-left:24px}
.d-nested-dialog-focus-return dialog{max-width:min(400px,calc(100vw - 32px));max-height:85vh;overflow:auto;border:1px solid var(--line);background:var(--paper);color:var(--ink);padding:16px}.d-nested-dialog-focus-return dialog::backdrop{background:rgb(0 0 0 / .35)}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const parent=q('[data-parent]'),child=q('[data-child]');q('[data-open]').onclick=()=>parent.showModal();q('[data-child-open]').onclick=()=>child.showModal();q('[data-child-close]').onclick=()=>child.close();q('[data-parent-close]').onclick=()=>parent.close();child.onclose=()=>q('[data-child-open]').focus();parent.onclose=()=>{q('[data-open]').focus();say('设置对话框已关闭');};})(root, q, qa, say);
}
